INSERT INTO notification_templates(key, subject, body) VALUES
 ('order_confirmed', 'We received your EAZyfoods order {{order_number}}', E'Thank you! Your payment of ${{total}} CAD was confirmed.\nEach store will now confirm your order. Track it any time:\n{{web_url}}/orders\n\nOrder {{order_number}}'),
 ('order_status', 'Order {{order_number}}: {{status}}', E'Your order {{order_number}} is now {{status}}.\n{{note}}\n\nDetails: {{web_url}}/orders'),
 ('vendor_new_order', 'New order {{order_number}} is waiting', E'You have a new paid order ({{order_number}}). Please accept or reject it promptly.\n\n{{web_url}}/vendor/orders'),
 ('refund_processed', 'Refund of ${{amount}} for order {{order_number}}', E'We have issued a refund of ${{amount}} CAD for order {{order_number}}. It can take several business days to appear on your statement.'),
 ('substitution_proposed', 'A store suggests a replacement for order {{order_number}}', E'A store cannot supply an item in order {{order_number}} and suggests a replacement at no extra charge. Please accept or decline:\n{{web_url}}/orders'),
 ('password_reset', 'Reset your EAZyfoods password', E'Use this link to choose a new password (valid for 1 hour):\n{{link}}\n\nIf you did not ask for this, you can ignore this email.'),
 ('email_verify', 'Confirm your email for EAZyfoods', E'Please confirm your email address:\n{{link}}'),
 ('vendor_approved', 'Your EAZyfoods store has been approved', E'Good news: {{name}} has been approved. You can publish products and start receiving orders.\n\n{{web_url}}/vendor');
INSERT INTO content_blocks(key, value) VALUES
 ('home_hero', '{"title":"African groceries,\\nfrom the stores you trust.","subtitle":"Browse Calgary’s African grocers by region. Compare each store’s own price and stock, then have it delivered."}'),
 ('announcement', '{"text":"","active":false}');
INSERT INTO pages(slug, title, body, needs_legal_review) VALUES
 ('how-it-works', 'How EAZyfoods works', E'## Shop by region or search\nBrowse products from African grocery stores in Calgary. Every store sets its own price and stock.\n\n## One basket, one delivery per store\nIf your basket has items from more than one store, each store prepares its own order, and each has its own delivery fee and arrival estimate. We show this before you pay.\n\n## Paying\nYou pay when you place your order. Your order is only confirmed once your payment is confirmed by our payment provider.', false),
 ('delivery-policy', 'Delivery policy', E'## Where we deliver\nWe deliver to the postal-code areas shown when you add an address. If your area is not served yet, we will tell you before you shop.\n\n## Fees and timing\nDelivery fees and estimated arrival times are shown per store at checkout. Estimates are not guarantees.\n\n## Handover code\nWhen your order is on its way you will see a 4-digit code on your order page. Give it to the driver on arrival so we know it reached you.', false),
 ('refund-policy', 'Refunds, missing items and substitutions', E'## Missing, wrong or damaged items\nReport the problem from your order page within 48 hours of delivery. Our team reviews every report and refunds the affected items when the report is confirmed.\n\n## Substitutions\nA store may suggest a replacement for an item it cannot supply. You will never be charged more for a replacement, and you can decline it for a refund of that item.\n\n## Cancellations\nYou can cancel for a full refund until the store accepts your order. After that, contact support.\n\n## Refund timing\nRefunds go back to your original payment method. Your bank may take several business days to show them.', false),
 ('faq', 'Frequently asked questions', E'## Can I order from several stores at once?\nYes. Each store fulfils its own part of your order, with its own delivery fee and arrival estimate.\n\n## Why do prices differ between stores?\nEvery store sets its own prices.\n\n## What if something I ordered is unavailable?\nThe store can propose a replacement at no extra charge, or refund that item.\n\n## How do I get help?\nOpen your order and choose “Report a problem”.', false),
 ('privacy', 'Privacy policy', E'DRAFT. This page must be reviewed by a qualified professional before launch.\n\nWe collect the information needed to take and deliver your orders (name, email, phone, delivery address), and the details of your orders. We do not store card numbers; payments are handled by our payment provider. You can download or delete your data from your account page. Marketing email is sent only if you opt in, and you can opt out at any time.', true),
 ('terms', 'Terms of service', E'DRAFT. These terms must be reviewed by a qualified professional before launch.\n\nEAZyfoods is a marketplace. Each store is responsible for the products it sells and their availability.', true);
